 "content": "def transform(grid):
    """Reflect the colored pattern horizontally into the zero rectangle."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    colored = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] not in (background, 0)]
    zeros = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    if not colored or not zeros:
        return out

    r0, r1 = min(r for r, _ in colored), max(r for r, _ in colored)
    c0, c1 = min(c for _, c in colored), max(c for _, c in colored)
    zr0, zr1 = min(r for r, _ in zeros), max(r for r, _ in zeros)
    zc0, zc1 = min(c for _, c in zeros), max(c for _, c in zeros)
    sh, sw = r1 - r0 + 1, c1 - c0 + 1
    th, tw = zr1 - zr0 + 1, zc1 - zc0 + 1
    if (sh, sw) != (th, tw):
        return out

    for dr in range(sh):
        for dc in range(sw):
            out[zr0 + dr][zc0 + dc] = grid[r0 + dr][c1 - dc]
    return out
